			"process", "Object", "Array", "Math", "String", "Map", "RegExp", "Set", "Error", "JSON",
			"undefined", "pathToFileURL", "fileURLToPath", "realpath", "resolve",
			"VerificationError", "classifyEntry", "entry", "main",
